-- 029: align saved FAQ copy with the October 2026 rental tariff
-- Removes 'no metered / no per-page' claims, A3 starting price AED 500 -> 350, adds the included pages and extra-page rates. Apply after the matching site release.
-- Scope: faqs rows faq-home-1, qa-spr-1, paa-spr-8, qa-pcr-1, qa-pcr-2, qa-rak-2, qa-auh-3, qa-dxb-2 only.
-- Each replace() is exact and idempotent: if the old text is absent it does nothing.
-- "Before" text was captured byte-exact from GET /api/faqs/ on 2026-10-23.

UPDATE faqs SET answer = replace(answer, 'AED 500–1,000/month. All plans include zero deposit, unlimited toner, maintenance, and free delivery.', 'AED 350–1,000/month. All plans include zero deposit, unlimited toner, maintenance, and free delivery. Pages above the included allowance are billed at AED 0.06 (B&W) and AED 0.20 (colour).') WHERE id = 'faq-home-1';
UPDATE faqs SET answer = replace(answer, 'One fixed monthly fee from AED 250 covers unlimited genuine OEM toner, scheduled preventive servicing, all parts and labour, and free delivery with network setup. There is no deposit, no metered page charge, and no exit fee.', 'A fixed monthly fee covers the machine, unlimited genuine OEM toner, scheduled preventive servicing, all parts and labour, and free delivery with network setup — from AED 250/month for a compact A4 desktop (2,000 B&W and 750 colour pages included) and AED 350/month for the standard A3 package (3,000 B&W and 1,000 colour pages included). Extra pages are billed at AED 0.06 (B&W) and AED 0.20 (colour). There is no deposit and no exit fee.') WHERE id = 'qa-spr-1';
UPDATE faqs SET supportingPoints = replace(supportingPoints, 'A4 desktop from AED 250/month; A3 mid-range AED 500-800; A3 enterprise AED 1,000-2,000', 'A4 desktop from AED 250/month (2,000 B&W + 750 colour pages included); A3 from AED 350/month (3,000 B&W + 1,000 colour pages included)') WHERE id = 'qa-spr-1';
UPDATE faqs SET supportingPoints = replace(supportingPoints, 'Unlimited genuine OEM toner is monitored and replenished proactively', 'Extra pages AED 0.06 B&W and AED 0.20 colour; Enterprise (from 10,000 B&W or 5,000 colour pages a month) is quoted by phone or visit') WHERE id = 'qa-spr-1';
UPDATE faqs SET answer = replace(answer, '— there are no metered per-page charges or hidden add-ons on Sahara''s standard plans.', '— with no hidden add-ons. A compact A4 plan includes 2,000 B&W and 750 colour pages a month and the standard A3 package includes 3,000 B&W and 1,000 colour pages; extra pages are billed at AED 0.06 (B&W) and AED 0.20 (colour).') WHERE id = 'paa-spr-8';
UPDATE faqs SET answer = replace(answer, 'rent from AED 500 per month', 'rent from AED 350 per month') WHERE id = 'qa-pcr-1';
UPDATE faqs SET supportingPoints = replace(supportingPoints, 'From AED 500/month with zero deposit', 'From AED 350/month with zero deposit') WHERE id = 'qa-pcr-1';
UPDATE faqs SET answer = replace(answer, 'runs from AED 500 to AED 2,000 per month. A3 mid-range multifunction copiers suited to 10-30 users sit at AED 500-800; high-volume enterprise copiers for large offices run AED 1,000-2,000. Every tier includes toner, maintenance, parts, and delivery at no extra cost.', 'runs from AED 350 to AED 2,000 per month. A3 mid-range multifunction copiers suited to 10-30 users sit at AED 350-900; high-volume enterprise copiers for large offices run AED 1,000-2,000 and are quoted by phone or visit. Every tier includes toner, maintenance, parts, and delivery; pages above the included allowance are billed at AED 0.06 (B&W) and AED 0.20 (colour).') WHERE id = 'qa-pcr-2';
UPDATE faqs SET supportingPoints = replace(supportingPoints, 'A3 mid-range AED 500-800/month for offices of 10-30 users', 'A3 mid-range AED 350-900/month for offices of 10-30 users') WHERE id = 'qa-pcr-2';
UPDATE faqs SET supportingPoints = replace(supportingPoints, 'A3 enterprise AED 1,000-2,000/month for high-volume departments', 'A3 enterprise AED 1,000-2,000/month for high-volume departments, quoted by phone or visit') WHERE id = 'qa-pcr-2';
UPDATE faqs SET supportingPoints = replace(supportingPoints, 'No deposit, no per-page metering, no exit fee at any tier', 'No deposit and no exit fee at any tier; extra pages above the allowance are billed at AED 0.06 (B&W) and AED 0.20 (colour)') WHERE id = 'qa-pcr-2';
UPDATE faqs SET answer = replace(answer, 'begins at AED 500', 'begins at AED 350') WHERE id = 'qa-rak-2';
UPDATE faqs SET supportingPoints = replace(supportingPoints, 'A3 multifunction from AED 500/month', 'A3 multifunction from AED 350/month') WHERE id = 'qa-rak-2';
UPDATE faqs SET answer = replace(answer, 'begin at AED 500', 'begin at AED 350') WHERE id = 'qa-auh-3';
UPDATE faqs SET supportingPoints = replace(supportingPoints, 'A3 multifunction from AED 500/month', 'A3 multifunction from AED 350/month') WHERE id = 'qa-auh-3';
UPDATE faqs SET answer = replace(answer, 'many Dubai quotes exclude toner or meter pages, so a low headline rate rises sharply in use. Sahara quotes one all-inclusive fee with zero deposit and no exit fee.', 'many Dubai quotes exclude toner or add charges later, so a low headline rate rises sharply in use. Sahara quotes one fixed monthly fee with zero deposit, no exit fee, and published extra-page rates (AED 0.06 B&W, AED 0.20 colour above the included allowance).') WHERE id = 'qa-dxb-2';
UPDATE faqs SET supportingPoints = replace(supportingPoints, 'Check for per-page metering, which makes low headline rates misleading', 'Check how extra pages are charged and whether the rate is published - Sahara publishes AED 0.06 (B&W) and AED 0.20 (colour)') WHERE id = 'qa-dxb-2';
